{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://tasknotes.dev/schemas/tasknotes-task.schema.json",
  "title": "TaskNotes portable task view",
  "description": "The storage-neutral record view exposed by the tasknotes.task 0.3.0-rc.3 record contract.",
  "type": "object",
  "required": [
    "status",
    "dateCreated"
  ],
  "additionalProperties": false,
  "properties": {
    "id": {
      "type": "string",
      "minLength": 1
    },
    "title": {
      "type": "string",
      "minLength": 1
    },
    "status": {
      "type": "string",
      "minLength": 1
    },
    "priority": {
      "type": "string",
      "minLength": 1
    },
    "due": {
      "anyOf": [
        {
          "type": "string",
          "format": "date"
        },
        {
          "type": "string",
          "format": "date-time"
        }
      ]
    },
    "scheduled": {
      "anyOf": [
        {
          "type": "string",
          "format": "date"
        },
        {
          "type": "string",
          "format": "date-time"
        }
      ]
    },
    "contexts": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "projects": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "attachments": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "minLength": 1
      }
    },
    "timeEstimate": {
      "type": "integer",
      "minimum": 0
    },
    "completedDate": {
      "type": "string",
      "format": "date"
    },
    "dateCreated": {
      "type": "string",
      "format": "date-time"
    },
    "dateModified": {
      "type": "string",
      "format": "date-time"
    },
    "recurrence": {
      "type": "string"
    },
    "recurrenceAnchor": {
      "enum": [
        "scheduled",
        "completion"
      ]
    },
    "recurrenceParent": {
      "type": "string"
    },
    "occurrenceDate": {
      "type": "string",
      "format": "date"
    },
    "occurrenceMaterialization": {
      "enum": [
        "manual",
        "on_completion",
        "rolling"
      ]
    },
    "occurrenceNextTrigger": {
      "enum": [
        "completion",
        "completion_or_skip"
      ]
    },
    "occurrenceTemplate": {
      "type": "string"
    },
    "occurrencePastHorizon": {
      "type": "string"
    },
    "occurrenceFutureHorizon": {
      "type": "string"
    },
    "tags": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "timeEntries": {
      "type": "array",
      "items": {
        "type": "object"
      }
    },
    "reminders": {
      "type": "array",
      "items": {
        "type": "object"
      }
    },
    "blockedBy": {
      "type": "array",
      "items": {
        "type": "object"
      }
    },
    "completeInstances": {
      "type": "array",
      "items": {
        "type": "string",
        "format": "date"
      }
    },
    "skippedInstances": {
      "type": "array",
      "items": {
        "type": "string",
        "format": "date"
      }
    },
    "icsEventId": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "googleCalendarEventId": {
      "type": "string"
    },
    "googleCalendarExceptionEventId": {
      "type": "string"
    },
    "googleCalendarExceptionOriginalScheduled": {
      "type": "string",
      "format": "date"
    },
    "googleCalendarMovedOriginalDates": {
      "type": "array",
      "items": {
        "type": "string",
        "format": "date"
      }
    },
    "sortOrder": {
      "type": "string"
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://tasknotes.dev/schemas/tasknotes-task-binding.schema.json",
  "title": "TaskNotes task data-contract binding",
  "description": "Semantic configuration supplied by an mdbase type that implements tasknotes.task 0.3.0-rc.3.",
  "type": "object",
  "required": [
    "profiles",
    "capabilities",
    "title",
    "status",
    "priority",
    "recurrence",
    "occurrences",
    "links",
    "archive",
    "time_tracking",
    "templating"
  ],
  "properties": {
    "profiles": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "enum": [
          "core-lite",
          "recurrence",
          "templating",
          "materialized-occurrences",
          "extended"
        ]
      }
    },
    "capabilities": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "enum": [
          "dependencies",
          "reminders",
          "attachments",
          "links",
          "time-tracking",
          "materialized-occurrences",
          "rename",
          "archive",
          "batch",
          "concurrency",
          "dry-run",
          "migration",
          "templating"
        ]
      }
    },
    "title": {
      "$ref": "#/$defs/titlePolicy"
    },
    "status": {
      "$ref": "#/$defs/statusPolicy"
    },
    "priority": {
      "$ref": "#/$defs/priorityPolicy"
    },
    "recurrence": {
      "$ref": "#/$defs/recurrencePolicy"
    },
    "occurrences": {
      "$ref": "#/$defs/occurrencePolicy"
    },
    "links": {
      "$ref": "#/$defs/linkPolicy"
    },
    "archive": {
      "$ref": "#/$defs/archivePolicy"
    },
    "time_tracking": {
      "$ref": "#/$defs/timeTrackingPolicy"
    },
    "templating": {
      "$ref": "#/$defs/templatingPolicy"
    },
    "nlp": {
      "$ref": "#/$defs/nlpPolicy"
    }
  },
  "additionalProperties": false,
  "$defs": {
    "nonEmptyString": {
      "type": "string",
      "minLength": 1
    },
    "stringSet": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/nonEmptyString"
      }
    },
    "titlePolicy": {
      "type": "object",
      "required": [
        "storage"
      ],
      "properties": {
        "storage": {
          "enum": [
            "filename",
            "frontmatter"
          ]
        },
        "filename_format": {
          "enum": [
            "title",
            "zettel",
            "timestamp",
            "uuid",
            "custom"
          ]
        },
        "custom_filename_template": {
          "$ref": "#/$defs/nonEmptyString"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "filename_format": {
                "const": "custom"
              }
            },
            "required": [
              "filename_format"
            ]
          },
          "then": {
            "properties": {
              "custom_filename_template": {
                "$ref": "#/$defs/nonEmptyString"
              }
            },
            "required": [
              "custom_filename_template"
            ]
          }
        }
      ],
      "additionalProperties": true
    },
    "statusDefinition": {
      "type": "object",
      "required": [
        "value",
        "label",
        "color",
        "is_completed",
        "is_skipped",
        "exclude_from_cycle",
        "order",
        "auto_archive",
        "auto_archive_delay_minutes"
      ],
      "properties": {
        "value": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "label": {
          "type": "string"
        },
        "color": {
          "type": "string"
        },
        "icon": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "is_completed": {
          "type": "boolean"
        },
        "is_skipped": {
          "type": "boolean"
        },
        "exclude_from_cycle": {
          "type": "boolean"
        },
        "next_status": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "order": {
          "type": "number"
        },
        "auto_archive": {
          "type": "boolean"
        },
        "auto_archive_delay_minutes": {
          "type": "number",
          "minimum": 0
        }
      },
      "additionalProperties": true
    },
    "statusPolicy": {
      "type": "object",
      "required": [
        "values",
        "default",
        "completed_values",
        "definitions"
      ],
      "properties": {
        "values": {
          "$ref": "#/$defs/stringSet"
        },
        "default": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "completed_values": {
          "$ref": "#/$defs/stringSet"
        },
        "skipped_values": {
          "$ref": "#/$defs/stringSet"
        },
        "default_skipped": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "definitions": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/statusDefinition"
          }
        }
      },
      "additionalProperties": false
    },
    "priorityDefinition": {
      "type": "object",
      "required": [
        "value",
        "label",
        "color",
        "weight"
      ],
      "properties": {
        "value": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "label": {
          "type": "string"
        },
        "color": {
          "type": "string"
        },
        "icon": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "weight": {
          "type": "number"
        }
      },
      "additionalProperties": true
    },
    "priorityPolicy": {
      "type": "object",
      "required": [
        "values",
        "default",
        "definitions"
      ],
      "properties": {
        "values": {
          "$ref": "#/$defs/stringSet"
        },
        "default": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "definitions": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/priorityDefinition"
          }
        }
      },
      "additionalProperties": false
    },
    "recurrencePolicy": {
      "type": "object",
      "required": [
        "syntax",
        "maintain_due_date_offset",
        "reset_body_checkboxes"
      ],
      "properties": {
        "syntax": {
          "const": "tasknotes"
        },
        "maintain_due_date_offset": {
          "type": "boolean"
        },
        "reset_body_checkboxes": {
          "type": "boolean"
        }
      },
      "additionalProperties": false
    },
    "occurrencePolicy": {
      "type": "object",
      "required": [
        "identity_roles",
        "default_materialization",
        "default_next_trigger"
      ],
      "properties": {
        "identity_roles": {
          "const": [
            "recurrenceParent",
            "occurrenceDate"
          ]
        },
        "default_materialization": {
          "enum": [
            "manual",
            "on_completion",
            "rolling"
          ]
        },
        "default_next_trigger": {
          "enum": [
            "completion",
            "completion_or_skip"
          ]
        },
        "past_horizon": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "future_horizon": {
          "$ref": "#/$defs/nonEmptyString"
        }
      },
      "additionalProperties": false
    },
    "linkPolicy": {
      "type": "object",
      "required": [
        "accepted_formats",
        "write_format"
      ],
      "properties": {
        "accepted_formats": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "enum": [
              "wikilink",
              "markdown"
            ]
          }
        },
        "write_format": {
          "enum": [
            "wikilink",
            "markdown"
          ]
        }
      },
      "additionalProperties": false
    },
    "archivePolicy": {
      "type": "object",
      "required": [
        "archived_tag",
        "move_on_archive"
      ],
      "properties": {
        "archived_tag": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "move_on_archive": {
          "type": "boolean"
        },
        "folder": {
          "$ref": "#/$defs/nonEmptyString"
        }
      },
      "additionalProperties": false
    },
    "timeTrackingPolicy": {
      "type": "object",
      "required": [
        "auto_stop_on_complete"
      ],
      "properties": {
        "auto_stop_on_complete": {
          "type": "boolean"
        }
      },
      "additionalProperties": false
    },
    "templatingPolicy": {
      "type": "object",
      "required": [
        "enabled",
        "occurrence_enabled"
      ],
      "properties": {
        "enabled": {
          "type": "boolean"
        },
        "template_path": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "occurrence_enabled": {
          "type": "boolean"
        },
        "occurrence_template_path": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "failure_mode": {
          "enum": [
            "error",
            "warning_fallback"
          ]
        },
        "unknown_variable_policy": {
          "enum": [
            "preserve",
            "empty"
          ]
        }
      },
      "additionalProperties": false
    },
    "nlpTrigger": {
      "type": "object",
      "required": [
        "property_id",
        "trigger",
        "enabled"
      ],
      "properties": {
        "property_id": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "trigger": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "enabled": {
          "type": "boolean"
        }
      },
      "additionalProperties": false
    },
    "nlpPolicy": {
      "type": "object",
      "required": [
        "triggers"
      ],
      "properties": {
        "triggers": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/nlpTrigger"
          }
        }
      },
      "additionalProperties": false
    }
  }
}
